// Composio toolkit overlay types — hand-authored Liftoff metadata atop
// Composio's vendor-defined schemas. See plan
// C2 for the design and authoring rules.

import type { ConnectorFunction, ToolErrorCode } from '@liftoffos/connector-types';

/** A frozen Composio vendor schema (one entry per Composio tool slug).
 *  Generated by scripts/sync-schemas.ts. NEVER hand-edited. */
export interface ComposioVendorSchema {
  /** Composio's vendor slug (e.g. 'GMAIL_FETCH_EMAILS', UPPER_SNAKE). */
  slug: string;
  /** Human-readable vendor name. */
  name: string;
  /** Vendor description; '' when Composio omits it. */
  description: string;
  /** Vendor JSON Schema; defaulted to {type:'object',properties:{}} when absent. */
  inputSchema: {
    type: 'object';
    properties: Record<string, unknown>;
    required?: string[];
    title?: string;
    description?: string;
    additionalProperties?: boolean;
  };
  /** Categories inferred by the script from name conventions (see C1 step 3). */
  categories: ConnectorFunction['categories'];
}

/** Hand-authored overlay for a single Composio tool. Keyed by VENDOR slug
 *  inside COMPOSIO_TOOL_OVERLAYS[toolkit][vendorSlug]. */
export interface ComposioToolOverlay {
  /** Liftoff-canonical agent-facing name (e.g. 'list_messages'). MUST be
   *  unique within the toolkit. Native counterparts MUST use the same name
   *  when one exists, so the stable name is interchangeable across sources. */
  stableName: string;

  /** Categories override. Set when the script's name-based inference is
   *  wrong (e.g. add 'outbound' for tools that cross trust boundaries). */
  categoryOverrides?: ConnectorFunction['categories'];

  /** Stable name of the draft-first variant tool, if any. */
  draftVariant?: string;

  /** Vendor arguments the overlay OWNS: ones `translateInput` supplies on
   *  the agent's behalf (a `user_id` that is always 'me', label ids the ack
   *  pre-fills) and ones it deliberately never forwards (a bot-identity field
   *  the canonical shape hides). Removed from the PUBLISHED schema (properties
   *  and required) by agentFacingInputSchema: the agent can neither see nor
   *  set them, and a schema that advertised one as required was asking the
   *  model for a value the overlay would overwrite or drop. Every name here is
   *  the VENDOR's. */
  overlayOwnedArgs?: string[];

  /** Vendor arguments the agent MAY set but `translateInput` defaults when
   *  absent (a reaction that defaults to eyes, a limit of 100). Kept in the
   *  published properties, removed from required: a contract must not demand
   *  what the overlay would fill in. Every name here is the VENDOR's. */
  defaultedArgs?: string[];

  /** Descriptions for agent-facing arguments the vendor schema leaves bare,
   *  keyed by the argument's advertised (vendor) name. What tells the model
   *  that `thread_id` is a thread's id and not a message's. */
  argDescriptions?: Record<string, string>;

  /** Optional addendum appended to the vendor description before the tool
   *  schema is published to the LLM. Use for guidance that the vendor
   *  description doesn't carry — e.g. disambiguating `reply_to_thread`
   *  vs `send_email` so the LLM doesn't emit both for the same response
   *  (observed for the CSR agent at 2026-06-12T21:31 UTC, where one
   *  invocation produced two drafts because both tools fired in a single
   *  step). Outlook gets the equivalent guidance for
   *  reply_to_message vs send_message. */
  descriptionSuffix?: string;

  /** W1 work_inbox/ack metadata. STABLE names on both sides. */
  workRole?: 'inbox' | 'ack';
  paired_ack?: string;           // on inbox: stable name of the ack tool
  acknowledges?: string;         // on ack:   stable name of the inbox tool
  workItemKind?: string;         // cross-connector label

  /** Reactive-subscription eligibility. Mirrors
   *  ConnectorFunction.metricReadable on the registry side. */
  metricReadable?: boolean;

  /** Write-provenance declarations. Mirror ConnectorFunction's fields of the
   *  same names; the registry copies them straight through.
   *
   *  These are stated in CANONICAL shape, not Composio's. `idArgs` names
   *  arguments the AGENT passes — the ones `translateInput` receives, not the
   *  ones it emits — and `returnsIds` paths are read against the CANONICAL
   *  response, after `translateOutput`. Stating them in vendor shape would
   *  compile, match nothing at runtime, and read as "declares nothing", which
   *  is indistinguishable from a tool nobody covered.
   *
   *  DECLARE BOTH SIDES OF A TOOLKIT OR NEITHER. A toolkit whose writes name
   *  their id arguments while none of its reads say what they return can only
   *  ever produce false positives: every write is judged, and nothing in the
   *  toolkit can ever provenance one. Enforced by
   *  __tests__/provenance-declaration-pairing.test.ts. */
  idArgs?: string[];
  returnsIds?: Array<{ entityType: string; path: string }>;
  egressOnly?: string[];
  writeRole?: 'stage' | 'apply' | 'direct';
  paired_apply?: string;

  /** Argument shape translation. Called with canonical Liftoff-shape args
   *  the agent passes, returns Composio-shape args.
   *  OMITTED ⇒ passthrough (canonical == Composio shape). */
  translateInput?: (canonical: Record<string, unknown>) => Record<string, unknown>;

  /** Response shape translation. Called with Composio's tool response data
   *  (resp.data — NOT the full ToolExecuteResponse envelope; the dispatcher
   *  unwraps that). MUST conform to the CANONICAL_RESPONSE_SHAPES entry for
   *  this stable name when one is registered.
   *  OMITTED ⇒ passthrough. */
  translateOutput?: (vendorRespData: unknown) => unknown;

  /** Error shape translation. Composio errors arrive as
   *  { code, message, data? }. The dispatcher catches and maps via this
   *  function (default: defaultComposioErrorMap from canonical-shapes.ts). */
  translateError?: (vendorErr: { code: number; message: string; data?: unknown }) => NormalizedToolError;

  /** Async pre-dispatch enrichment. Runs in the runtime AFTER translateInput
   *  has shaped the Composio-side args but BEFORE the vendor tool fires.
   *  Use for fields that can only be derived from a sibling vendor call —
   *  e.g. when GMAIL_REPLY_TO_THREAD is substituted to GMAIL_CREATE_EMAIL_DRAFT
   *  under `communication: 'draft'`, the draft needs a `recipient_email` that
   *  the agent never passed; this hook can fetch the thread and fill it in
   *  from the original sender. Symmetric path applies to OUTLOOK_CREATE_DRAFT.
   *
   *  `ctx.dispatchVendor` is bound by the runtime to the same Composio
   *  connection (tenantId / connectedAccountId / connectorInstanceId) that
   *  the outer call uses, so the lookup reads the same mailbox. Returns the
   *  args that will actually be passed to the vendor tool — return the input
   *  unchanged when no enrichment applies.
   *
   *  OMITTED ⇒ no enrichment (dispatcher uses translateInput's output as-is). */
  enrichBeforeExecute?: (
    args: Record<string, unknown>,
    ctx: {
      dispatchVendor: (
        vendorSlug: string,
        vendorArgs: Record<string, unknown>,
      ) => Promise<unknown>;
    },
  ) => Promise<Record<string, unknown>>;

  /** OPTIONAL: long-running operation handling. When set, the dispatcher
   *  fires the initial Composio call, extracts the job id from resp.data,
   *  then loops calling the named status-query tool until completeWhen()
   *  returns true. Each poll tick consumes one rate-limit slot AND emits one
   *  reportComposioToolCall (Composio bills per attempt). */
  polling?: {
    /** Stable name of the status-query tool in the SAME toolkit. */
    statusToolStableName: string;
    /** Field in the status response indicating completion (e.g. 'status'). */
    stateField: string;
    /** Returns true when state indicates terminal success. */
    completeWhen: (state: unknown) => boolean;
    /** Returns true when state indicates terminal failure (then translateError fires). */
    failedWhen?: (state: unknown) => boolean;
    /** Maximum polling iterations before throwing polling_timeout. */
    maxAttempts: number;
    /** Sleep between attempts. */
    intervalMs: number;
    /** Field in the initial response carrying the job id. */
    jobIdField: string;
    /** Field name in the status tool's input where the job id is passed. */
    statusToolJobIdField: string;
  };
}

/** Maps a connector's historyReads entry (read_<entityType>) to a Composio
 *  vendor tool. C3's merge step uses this to emit registry entries for
 *  composio_managed history tools. */
export interface HistoryToolMapping {
  /** Matches CONNECTORS[type].historyReads[i].entityType. */
  entityType: string;
  /** Canonical history-tool stable name (convention: 'read_<entityType>'). */
  stableName: string;
  /** Composio vendor tool that backs this history read. */
  vendorToolName: string;
  translateInput?: (canonical: Record<string, unknown>) => Record<string, unknown>;
  translateOutput?: (vendorRespData: unknown) => unknown;
  /** What this history read hands back, in CANONICAL shape. A history read is
   *  the archetypal provenance source — it is how a run learns which records
   *  exist — so leaving it undeclared silently withholds the ids most likely to
   *  be acted on next. Same meaning as ComposioToolOverlay.returnsIds. */
  returnsIds?: Array<{ entityType: string; path: string }>;
}

/** Normalized error surfaced to agents regardless of source (native or composio).
 *  `code` is the shared canonical taxonomy (ToolErrorCode) so connector-service,
 *  tenant-runtime, and these overlays all speak one vocabulary. */
export interface NormalizedToolError extends Error {
  code: ToolErrorCode;
  /** Whether the agent should auto-retry. */
  retryable: boolean;
  /** Milliseconds to wait before a retry when the vendor supplied a Retry-After
   *  (rate_limited path). Undefined when the vendor gave no hint. */
  retryAfterMs?: number;
  /** Raw vendor payload for debugging — NOT shown to the agent. */
  vendorPayload?: unknown;
}
